#page_body.section div.widget.FeaturedPost,div.widget.PopularPosts{
padding:16px
}
div.widget.Blog .blog-posts .post-outer-container{
padding:16px
}
div.widget.Blog .blog-posts .post-outer-container .post-outer{
padding:0
}
.post:first-child{
margin:0
}
.post-body .snippet-thumbnail{
margin:0 3vw 3vw 0
}
.post-body .snippet-thumbnail img{
height:20vw;
width:20vw;
max-height:128px;
max-width:128px
}
div.widget.PopularPosts div.item-thumbnail{
margin:0 3vw 3vw 0
}
div.widget.PopularPosts div.item-thumbnail img{
height:20vw;
width:20vw;
max-height:88px;
max-width:88px
}
.post-title{
line-height:1
}
.post-title,.post-title a{
font-size:20px
}
#page_body.section div.widget.FeaturedPost h3 a{
font-size:22px
}
.mobile-ad .inline-ad{
display:block
}
.page_body.has-vertical-ads .vertical-ad-container,.page_body.has-vertical-ads .vertical-ad-container ins{
display:none
}
.page_body.has-vertical-ads .centered .centered-bottom,.page_body.has-vertical-ads .centered .centered-top{
display:block;
width:auto
}
div.post-filter-message div{
padding:8px 16px
}
}
@media screen and (min-width:$(sidebar.width + content.width + content.margin * 2)){
body{
position:relative
}
body.item-view .blog-name{
margin-left:48px
}
.page_body{
margin-left:$(sidebar.width)
}
.search{
margin-left:0
}
.search.focused{
width:100%
}
.sticky{
padding-left:$(sidebar.width)
}
.hamburger-menu{
display:none
}
body.collapsed-header .page_body .centered-top-container{
padding-left:$(sidebar.width);
padding-right:0;
width:100%
}
body.collapsed-header .centered-top-container .search.focused{
width:100%
}
body.collapsed-header .centered-top-container .blog-name{
margin-left:0
}
body.collapsed-header.item-view .centered-top-container .search.focused{
width:calc(100% - 50px)
}
body.collapsed-header.item-view .centered-top-container .blog-name{
margin-left:40px
}
}
/* Coupon launch layout: preserve Blogger native post rendering. */
body{background:#f6f7f9!important;color:#16202c!important}.bg-photo,.bg-photo-overlay{display:none!important}.centered-top-container{background:#fff!important}.Header h1{font-size:30px!important}.post-title{font-size:25px!important}.post-body{font-size:16px!important;line-height:1.8!important}.post-body a{color:#2259cc}.post-outer{border-radius:16px!important}.post-body section{margin:22px 0;padding:18px;border:1px solid #e5e7eb;border-radius:12px}.post-body table{display:block;max-width:100%;overflow-x:auto}.post-body img{max-width:100%;height:auto}@media(max-width:600px){.post-body{font-size:15px!important}.post-title{font-size:22px!important}.post-body section{padding:12px}.centered{max-width:100%!important}}
/* R3 coupon shell; native Blogger widgets remain intact. */
:root{--ncp-ink:#172033;--ncp-blue:#2457d6;--ncp-line:#e2e8f0}
body{margin:0!important;padding:0!important;background:#f4f6f8!important}.centered-top-container,.centered-top-placeholder,.sidebar-container,.bg-photo,.bg-photo-overlay{display:none!important}.page_body{padding-top:0!important}.centered{padding-top:0!important;max-width:1180px!important}.ncp-home .page{display:none!important}
.ncp-r3{font-family:Arial,'Noto Sans KR',sans-serif;color:var(--ncp-ink)}.ncp-r3 a{text-decoration:none;color:var(--ncp-blue)}.ncp-r3-wrap{max-width:1180px;margin:auto;padding:24px}.ncp-r3-header{background:#fff;border-bottom:1px solid var(--ncp-line)}.ncp-r3-head{display:flex;align-items:center;gap:24px;flex-wrap:wrap}.ncp-r3-logo{font-size:26px;font-weight:800}.ncp-r3-search{display:flex;flex:1;min-width:240px;gap:8px}.ncp-r3 input{flex:1;min-width:0;padding:13px;border:1px solid var(--ncp-line);border-radius:10px}.ncp-r3 button,.ncp-r3-link{min-height:44px;padding:12px 16px;border:0;border-radius:10px;background:var(--ncp-blue);color:white!important;font-weight:700;cursor:pointer}.ncp-r3-rail{display:flex;gap:8px;overflow-x:auto;padding-top:0}.ncp-r3-chip{white-space:nowrap;padding:10px 14px;background:#edf2ff;border-radius:22px;font-size:14px}.ncp-r3-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.ncp-r3-card{padding:24px;border:1px solid var(--ncp-line);border-radius:16px;background:white;min-width:0}.ncp-r3 h1{font-size:36px;line-height:1.3}.ncp-r3 h2{margin:28px 0 16px;font-size:24px}.ncp-r3 h3{font-size:20px}.ncp-r3 p{line-height:1.8}.ncp-r3 code{display:block;padding:16px;background:#edf2ff;border-radius:10px;font-size:22px;overflow-wrap:anywhere}.ncp-r3-badge{display:inline-block;padding:6px 10px;background:#e8f6ed;border-radius:8px;font-size:13px}.ncp-r3-muted{color:#64748b;font-size:14px}.ncp-r3-footer{border-top:1px solid var(--ncp-line);margin-top:32px;background:white}.ncp-r3-copy-state{min-height:24px}.ncp-r3-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}
.ncp-feed-preview{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:12px 0 6px}.ncp-feed-stat{min-width:0;padding:12px 14px;border:1px solid var(--ncp-line);border-radius:10px;background:#f8fafc}.ncp-feed-stat span{display:block;margin-bottom:3px;color:#64748b;font-size:12px;font-weight:700}.ncp-feed-stat strong{display:block;color:#172033;font-size:15px;line-height:1.45;overflow-wrap:anywhere}.ncp-feed-preview-generic .ncp-feed-stat strong{font-size:14px}
@media(max-width:700px){.ncp-feed-preview{grid-template-columns:1fr;gap:8px}.ncp-r3-wrap{padding:16px}.ncp-r3-grid{grid-template-columns:1fr}.ncp-r3 h1{font-size:28px}.ncp-r3-head{gap:16px}.ncp-r3-search{flex-basis:100%}.ncp-r3-card{padding:18px}.ncp-r3-rail{padding-top:0}.centered{padding:0!important}}
/* 구현 예시. 실제 테마 selector/변수와 충돌 여부 확인. */
.ncp-game-grid{
  --ncp-game-cols:4;
  --ncp-game-gap:10px;
  display:flex;
  flex-wrap:wrap;
  justify-content:center;
  gap:var(--ncp-game-gap);
  width:100%;
  margin:0 auto;
}
.ncp-game-card{
  flex:0 0 calc((100% - (var(--ncp-game-gap) * (var(--ncp-game-cols) - 1))) / var(--ncp-game-cols));
  min-width:0;
  display:flex;
  flex-direction:column;
  align-items:center;
  text-align:center;
  text-decoration:none;
  box-sizing:border-box;
  padding:8px 2px 10px;
}
.ncp-game-icon-wrap{display:block;width:60px;aspect-ratio:1/1;overflow:hidden;border-radius:14px}
.ncp-game-icon{display:block;width:100%;height:100%;object-fit:cover}
.ncp-game-name{display:-webkit-box;margin-top:7px;max-width:100%;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2;font-size:12px;line-height:1.25;word-break:keep-all}
.ncp-game-updated{margin-top:3px;font-size:10px;line-height:1.2;opacity:.64}
.ncp-game-card:focus-visible{outline:2px solid currentColor;outline-offset:3px}
@media (min-width:480px){.ncp-game-grid{--ncp-game-cols:5;--ncp-game-gap:12px}.ncp-game-icon-wrap{width:64px}.ncp-game-name{font-size:13px}.ncp-game-updated{font-size:11px}}
@media (min-width:768px){.ncp-game-grid{--ncp-game-cols:6;--ncp-game-gap:14px}.ncp-game-icon-wrap{width:68px}}
@media (min-width:1024px){.ncp-game-grid{--ncp-game-cols:7;--ncp-game-gap:16px}.ncp-game-icon-wrap{width:76px}.ncp-game-name{font-size:14px}}
@media (min-width:1280px){.ncp-game-grid{--ncp-game-cols:8;--ncp-game-gap:18px}.ncp-game-icon-wrap{width:82px}}
/* Selected bright marketplace home. */
.ncp-home{background:#fff!important}.ncp-r4{font-family:Arial,'Noto Sans KR',sans-serif;color:#142346}.ncp-r4-wrap{max-width:1240px;margin:auto;padding:24px}.ncp-r4-top{display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid #edf1f7}.ncp-r4-logo{font-size:28px;font-weight:900;color:#1958df!important;text-decoration:none}.ncp-r4-top p{font-size:14px;color:#67788e}.ncp-r4-hero{background:#f4f8ff}.ncp-r4-hero-inner{display:grid;grid-template-columns:1.5fr 1fr;align-items:center;gap:24px;padding-top:32px;padding-bottom:32px}.ncp-r4-eyebrow{color:#245adf;font-weight:700;font-size:15px}.ncp-r4 h1{font-size:38px;line-height:1.35;letter-spacing:-1.5px;margin:12px 0 20px}.ncp-r4-search{display:flex;background:#fff;border:1px solid #cbd9f5;border-radius:12px;padding:6px;gap:8px}.ncp-r4-search input{width:100%;min-width:0;border:0;padding:12px;font-size:16px;background:transparent}.ncp-r4 button,.ncp-r4-button{border:0;border-radius:8px;background:#1858e9;color:#fff!important;padding:12px 20px;font-size:14px;font-weight:700;text-decoration:none;cursor:pointer;min-height:44px}.ncp-r4-hero img{width:100%;max-height:270px;object-fit:contain}.ncp-r4-sub{font-size:14px;color:#65738a;margin:12px 0 0}.ncp-r4-categories{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:14px;padding-top:24px;padding-bottom:20px}.ncp-r4-category{text-align:center;text-decoration:none;color:#233956!important;font-size:13px;font-weight:700;min-width:0}.ncp-r4-category span{display:flex;align-items:center;justify-content:center;height:70px;background:#f3f7fd;border-radius:15px;margin-bottom:9px}.ncp-r4-category:nth-child(3n+2) span{background:#f0fafb}.ncp-r4-category:nth-child(3n) span{background:#fff4f1}.ncp-r4-category img{width:38px;height:38px}.ncp-r4-section-head{display:flex;align-items:baseline;justify-content:space-between;gap:16px;margin:12px 0 16px}.ncp-r4 h2{font-size:25px;letter-spacing:-.7px;margin:0}.ncp-r4-section-head a{font-size:14px;text-decoration:none;color:#1858e9}.ncp-r4-game-list{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:16px}.ncp-r4-card{border:1px solid #e4eaf4;border-radius:14px;overflow:hidden;background:#fff;min-width:0;transition:transform .15s,box-shadow .15s}.ncp-r4-card:hover{transform:translateY(-3px);box-shadow:0 8px 24px #14234612}.ncp-r4-cover{display:block;width:100%;height:150px;object-fit:cover;background:#f2f6fc}.ncp-r4-card-body{padding:15px}.ncp-r4-card h3{font-size:17px;line-height:1.45;margin:0 0 8px;overflow-wrap:anywhere}.ncp-r4-card p{font-size:12px;color:#697a92;line-height:1.6;margin:0 0 12px}.ncp-r4-card a{color:#142346;text-decoration:none}.ncp-r4-card .ncp-r4-detail{display:block;text-align:center;padding:10px;border-radius:8px;background:#edf3ff;color:#1858e9;font-size:13px;font-weight:700;min-height:20px}.ncp-r4-latest-list{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.ncp-r4-latest-list .ncp-r4-cover{height:100px;object-fit:contain;padding:12px;box-sizing:border-box}.ncp-r4-status{font-size:14px;color:#67788e}.ncp-r4-bottom{margin-top:28px;border-top:1px solid #e6edf5;display:flex;justify-content:space-between;align-items:center;gap:20px;font-size:13px;color:#67788e}.ncp-r4-bottom a{color:#1858e9}.ncp-r4 a:focus-visible,.ncp-r4 button:focus-visible,.ncp-r4 input:focus-visible{outline:3px solid #6d9eff;outline-offset:3px}
@media(max-width:900px){.ncp-r4-categories{grid-template-columns:repeat(5,minmax(0,1fr))}.ncp-r4-game-list{grid-template-columns:repeat(3,minmax(0,1fr))}.ncp-r4-latest-list{grid-template-columns:repeat(3,minmax(0,1fr))}.ncp-r4 h1{font-size:30px}}
@media(max-width:600px){.ncp-r4-wrap{padding:18px}.ncp-r4-top p{display:none}.ncp-r4-logo{font-size:25px}.ncp-r4-hero-inner{grid-template-columns:1fr;gap:8px}.ncp-r4-hero img{height:170px;grid-row:1}.ncp-r4 h1{font-size:27px;letter-spacing:-1px}.ncp-r4-eyebrow{font-size:13px}.ncp-r4-categories{gap:14px 7px}.ncp-r4-category{font-size:11px}.ncp-r4-category span{height:54px;border-radius:12px}.ncp-r4-category img{width:30px;height:30px}.ncp-r4-game-list,.ncp-r4-latest-list{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.ncp-r4-cover{height:130px}.ncp-r4-card-body{padding:12px}.ncp-r4-card h3{font-size:15px}.ncp-r4 h2{font-size:22px}.ncp-r4-bottom{align-items:flex-start;flex-direction:column}.ncp-r4-search button{padding:12px 16px}}

.ncp-r4-search button{flex:none;white-space:nowrap;min-width:72px}.ncp-r4-card{display:flex;flex-direction:column}.ncp-r4-card-body{display:flex;flex-direction:column;flex:1}.ncp-r4-card .ncp-r4-detail{margin-top:auto}

/* Category pages share the selected home visual system. */
.ncp-r4-category-header{background:#fff;border-bottom:1px solid #edf1f7}.ncp-r4-category-header .ncp-r4-search{flex:1;max-width:800px}.ncp-category-page{background:#fff!important}.ncp-category-page .status-msg-wrap,.ncp-category-page .status-msg-body,.ncp-category-page .status-msg-border{display:none!important}
#ncp-game-hub{max-width:1240px;margin:auto;padding:24px;box-sizing:border-box}#ncp-game-hub h1{font-size:30px;margin:0 0 26px;color:#142346}.ncp-category-page .centered{max-width:1240px!important}
#ncp-game-hub .ncp-game-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:18px;justify-content:initial}#ncp-game-hub .ncp-game-card{padding:0;border:1px solid #e4eaf4;border-radius:14px;overflow:hidden;background:#fff;transition:transform .15s;align-items:stretch;text-align:left;color:#142346}#ncp-game-hub .ncp-game-card:hover{transform:translateY(-3px)}#ncp-game-hub .ncp-game-icon-wrap{width:100%;height:150px;aspect-ratio:auto;border-radius:0;background:#f3f7fc}#ncp-game-hub .ncp-game-name{margin:14px 14px 5px;font-size:16px;line-height:1.5}#ncp-game-hub .ncp-game-updated{margin:0 14px 16px;font-size:12px;color:#697a92;opacity:1}#ncp-game-hub [role='status']{padding:16px;background:#f5f8fd;border-radius:12px;color:#65738a}#ncp-game-hub [role='status']:empty{display:none}
@media(max-width:900px){#ncp-game-hub .ncp-game-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:600px){.ncp-r4-category-header .ncp-r4-top{flex-wrap:wrap}.ncp-r4-category-header .ncp-r4-search{flex-basis:100%}#ncp-game-hub{padding:18px}#ncp-game-hub h1{font-size:25px}#ncp-game-hub .ncp-game-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}#ncp-game-hub .ncp-game-icon-wrap{height:140px}#ncp-game-hub .ncp-game-name{font-size:14px}}

.ncp-category-page .centered{margin:0 auto!important;width:100%!important;box-sizing:border-box}.ncp-category-page .post-filter-message{display:none!important}.ncp-category-page .centered-bottom{padding:0!important}


/* White veil game cards: real current coupon counts. */
.ncp-game-visual{position:relative;background:#fff!important}
.ncp-r4-game-list .ncp-game-visual .ncp-r4-cover,#ncp-game-hub .ncp-game-visual .ncp-game-icon{opacity:.23;filter:blur(1.5px);transform:scale(1.03)}
.ncp-r4-game-list .ncp-game-visual .ncp-r4-card-body h3{position:absolute;top:75px;left:14px;right:14px;transform:translateY(-50%);margin:0;text-align:center;font-size:19px;line-height:1.4;font-weight:800;z-index:2;text-shadow:0 1px 5px #fff}
#ncp-game-hub .ncp-game-visual .ncp-game-icon-wrap{position:relative;overflow:hidden;background:#fff}
#ncp-game-hub .ncp-game-visual .ncp-game-name{position:absolute;top:50%;left:14px;right:14px;transform:translateY(-50%);margin:0;text-align:center;font-size:19px;line-height:1.4;font-weight:800;color:#142346;z-index:2;text-shadow:0 1px 5px #fff}
.ncp-coupon-count{position:absolute;top:10px;left:10px;z-index:3;display:inline-flex;align-items:center;padding:5px 9px;border-radius:8px;background:#2457d6;color:#fff;font-size:12px;font-weight:800;line-height:1.4;box-shadow:0 2px 6px #14234615}
#ncp-game-hub .ncp-game-visual .ncp-game-updated{margin-top:12px}
@media(max-width:600px){.ncp-r4-game-list .ncp-game-visual .ncp-r4-card-body h3,#ncp-game-hub .ncp-game-visual .ncp-game-name{font-size:17px;left:10px;right:10px}}

/* Keep artwork sharp; blur only the background behind the game name. */
.ncp-r4-game-list .ncp-game-visual .ncp-r4-cover,#ncp-game-hub .ncp-game-visual .ncp-game-icon{opacity:1;filter:none;transform:none}
.ncp-r4-game-list .ncp-game-visual .ncp-r4-card-body h3,#ncp-game-hub .ncp-game-visual .ncp-game-name{background:rgba(255,255,255,.76);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);padding:7px 8px;border-radius:9px;box-sizing:border-box;text-shadow:none;box-shadow:0 2px 10px #14234612}

/* Compact game titles and image-only home cards. */
.ncp-r4-game-list .ncp-game-visual .ncp-r4-card-body h3,#ncp-game-hub .ncp-game-visual .ncp-game-name{left:50%;right:auto;width:max-content;max-width:calc(100% - 24px);transform:translate(-50%,-50%);font-size:16px;font-weight:600;line-height:1.4;letter-spacing:-.3px;padding:6px 10px;border-radius:7px;word-break:keep-all;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;box-shadow:none}
.ncp-r4-game-list .ncp-game-visual .ncp-r4-card-body{padding:0}
.ncp-coupon-count{font-size:11px;font-weight:600;padding:4px 8px;border-radius:999px;box-shadow:none}
.ncp-game-cover-link{display:block}

/* Dense four-column mobile coupon grids. */
@media(max-width:600px){
.ncp-r4-game-list,.ncp-r4-latest-list,#ncp-game-hub .ncp-game-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.ncp-r4-game-list .ncp-r4-cover,#ncp-game-hub .ncp-game-icon-wrap{height:auto;aspect-ratio:1}
.ncp-r4-card,#ncp-game-hub .ncp-game-card{border-radius:10px}
.ncp-r4-game-list .ncp-game-visual .ncp-r4-card-body h3,#ncp-game-hub .ncp-game-visual .ncp-game-name{top:56%;font-size:11px;line-height:1.3;max-width:calc(100% - 8px);padding:4px;border-radius:5px;letter-spacing:-.3px}
.ncp-coupon-count{top:4px;left:4px;font-size:9px;padding:2px 5px}
.ncp-r4-latest-list .ncp-r4-cover{height:auto;aspect-ratio:1;padding:6px}
.ncp-r4-latest-list .ncp-r4-card-body{padding:7px 5px}
.ncp-r4-latest-list h3{font-size:11px;line-height:1.45;margin:0;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
#ncp-game-hub .ncp-game-updated{font-size:10px;margin:6px 5px 8px}
}

/* Keep game names readable in narrow mobile cards. */
@media(max-width:600px){
.ncp-r4-game-list .ncp-game-visual .ncp-r4-card-body h3,#ncp-game-hub .ncp-game-visual .ncp-game-name{font-size:10px;line-height:1.35;word-break:normal;overflow-wrap:anywhere;-webkit-line-clamp:3;max-width:calc(100% - 6px);padding:4px 3px}
.ncp-r4-section-head h2{white-space:nowrap;flex-shrink:0}
.ncp-r4-section-head p{font-size:11px;text-align:right}
}

/* Twelve-item coupon pagination. */
.ncp-r4-pager{display:flex;justify-content:flex-end;align-items:center;gap:12px;margin-top:14px}.ncp-r4-pager span{font-size:12px;color:#65738a}.ncp-r4 .ncp-r4-pager button{width:44px;height:44px;min-height:44px;padding:0;font-size:21px;border-radius:50%;background:#edf3ff;color:#1858e9!important}.ncp-r4-pager button:disabled{opacity:.35;cursor:default}

/* Unified browse controls and animated coupon pages. */
.ncp-r4-section-head .ncp-r4-view-all{display:inline-flex;align-items:center;gap:7px;padding:8px 12px;background:#f0f5ff;border:1px solid #e0e9fb;border-radius:999px;color:#2355c8;font-size:12px;font-weight:600;white-space:nowrap;transition:background .18s,box-shadow .18s}
.ncp-r4-view-all:after{content:'';width:6px;height:6px;border-top:1.5px solid currentColor;border-right:1.5px solid currentColor;transform:rotate(45deg)}
.ncp-r4-view-all:hover{background:#e5eeff;box-shadow:0 2px 8px #2355c812}
.ncp-r4-pager{gap:10px;margin-top:18px;padding:2px 0}.ncp-r4-pager span{min-width:44px;text-align:center;font-size:12px;font-weight:600;font-variant-numeric:tabular-nums;color:#67748a}
.ncp-r4 .ncp-r4-pager button{display:inline-flex;align-items:center;justify-content:center;width:40px;height:40px;min-height:40px;border:1px solid #dce5f4;background:#fff;color:#254fc2!important;box-shadow:0 2px 5px #14234608;transition:background .18s,transform .18s,box-shadow .18s}
.ncp-r4 .ncp-r4-pager button:last-child:not(:disabled){background:#2457dc;border-color:#2457dc;color:#fff!important;box-shadow:0 3px 10px #2457dc22}
.ncp-r4-pager button:hover:not(:disabled){transform:translateY(-1px);box-shadow:0 4px 12px #2457dc22}.ncp-r4 .ncp-r4-pager button:disabled{background:#f5f7fa;border-color:#edf0f5;color:#b4bfce!important;opacity:1;box-shadow:none}
.ncp-r4-pager button:focus-visible,.ncp-r4-view-all:focus-visible{outline:3px solid #8eb5ff;outline-offset:3px}

head.b:template-skin:

body#layout .hidden,
body#layout .invisible {
  display: inherit;
}
body#layout .navigation {
  display: none;
}
body#layout .page,
body#layout .sidebar_top,
body#layout .sidebar_bottom {
  display: inline-block;
  left: inherit;
  position: relative;
  vertical-align: top;
}
body#layout .page {
  float: right;
  margin-left: 20px;
  width: 55%;
}
body#layout .sidebar-container {
  float: right;
  width: 40%;
}
body#layout .hamburger-menu {
  display: none;
}

body.script:
//
document.addEventListener('click',async function(event){const button=event.target.closest('[data-ncp-copy]');if(!button)return;const scope=button.closest('.ncp-coupon-card,.ncp-r3-card,article')||document;const status=scope.querySelector('[role="status"]');const before=button.textContent;button.disabled=true;try{await navigator.clipboard.writeText(button.dataset.ncpCopy||'');button.textContent='복사됨';if(status)status.textContent='코드를 복사했습니다.';}catch{button.textContent='복사 실패';if(status)status.textContent='자동 복사가 제한됩니다. 코드를 선택해 복사하세요.';}finally{window.setTimeout(function(){button.textContent=before;button.disabled=false;},1400);}});
//

b:if.script:
//
// Only mounted by the Blogger label condition.
(async function(){
  const root=document.getElementById('ncp-game-hub');
  if(!root)return;
  const category=root.dataset.category||'게임';
  const grid=root.querySelector('.ncp-game-grid');
  const status=root.querySelector('[role="status"]');
  try{
    const response=await fetch('/feeds/posts/default/-/'+encodeURIComponent(category)+'?alt=json&max-results=150');
    if(!response.ok)throw Error('FEED_HTTP');
    const feed=await response.json();
    const seen=new Set();
    for(const entry of feed.feed.entry||[]){
      const name=(entry.category||[]).map(x=>x.term).find(x=>x!==category)||entry.title?.$t;
      const url=(entry.link||[]).find(x=>x.rel==='alternate')?.href;
      if(!name||!url||seen.has(name)||new URL(url,location.href).origin!==location.origin)continue;
      seen.add(name);
      const card=document.createElement('a');card.className='ncp-game-card'+(category==='게임'?' ncp-game-visual':'');card.href=url;card.setAttribute('aria-label',name+' 쿠폰 보기');
      const wrap=document.createElement('span');wrap.className='ncp-game-icon-wrap';
      const image=document.createElement('img');image.className='ncp-game-icon';image.alt=name;image.loading='lazy';image.decoding='async';
      const content=new DOMParser().parseFromString(entry.content?.$t||'','text/html');
      const codeCount=new Set([...content.querySelectorAll('[data-ncp-copy]')].map(el=>el.getAttribute('data-ncp-copy')).filter(Boolean)).size;
      const src=content.querySelector('img')?.getAttribute('src')||entry.media$thumbnail?.url||'https://api.iconify.design/twemoji/video-game.svg';
      image.referrerPolicy='no-referrer';
      if(src&&new URL(src,location.href).protocol==='https:'){
        const iconUrl=new URL(src,location.href);
        if(iconUrl.hostname==='play-lh.googleusercontent.com')iconUrl.pathname=iconUrl.pathname.replace(/=[^/]*$/, '=w240-h240-rw');
        image.src=iconUrl.href;
        image.addEventListener('error',()=>{
          const fallback=entry.media$thumbnail?.url;
          if(fallback&&fallback!==image.src&&new URL(fallback,location.href).protocol==='https:')image.src=fallback;
          else image.src='https://api.iconify.design/twemoji/video-game.svg';
        },{once:true});
      }
      if(src)wrap.append(image);
      else{wrap.textContent=name.slice(0,2);wrap.setAttribute('aria-hidden','true');}
      const title=document.createElement('strong');title.className='ncp-game-name';title.textContent=name;
      const date=document.createElement('span');date.className='ncp-game-updated';
      const updated=new Date(entry.updated?.$t);
      if(!Number.isNaN(updated.getTime())){
        const parts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Seoul',month:'2-digit',day:'2-digit'}).formatToParts(updated);
        date.textContent=parts.find(x=>x.type==='month').value+'.'+parts.find(x=>x.type==='day').value+' 업데이트';
      }else date.textContent='업데이트 날짜 미확인';
      if(category==='게임'){
        date.textContent=codeCount>0?'코드 '+codeCount+'개 · 사용 여부는 본문 확인':'쿠폰 안내';
        wrap.append(title);
        if(codeCount>0){const badge=document.createElement('span');badge.className='ncp-coupon-count';badge.textContent='코드 '+codeCount+'개';wrap.append(badge);}
        card.append(wrap,date);
      }else card.append(wrap,title,date);
      grid.append(card);
    }
    status.textContent=grid.children.length?'':'등록된 쿠폰 안내가 없습니다.';
  }catch{status.textContent='목록을 불러오지 못했습니다. 잠시 후 다시 확인해주세요.';}
})();


//

//
// Home R4: public Blogger feed, no fabricated coupon status or benefit.
(async function(){
  const root=document.getElementById('ncp-home-r4');if(!root)return;
  const allowed=['게임','유심·로밍','호스팅·도메인','해외직구','건강','VPN','교육'];
  const status=root.querySelector('[role="status"]');
  // These are published game guides, not proof of currently redeemable coupons.
  const guideCodeCount=entry=>new Set([...String(entry.content?.$t||'').matchAll(/data-ncp-copy=["']([^"']+)["']/g)].map(match=>match[1])).size;
  function card(entry,game,count){
    const url=entry.link?.find(x=>x.rel==='alternate')?.href;
    if(!url||new URL(url,location.href).origin!==location.origin)return null;
    const labels=(entry.category||[]).map(x=>x.term);
    const name=game?(labels.find(x=>x!=='게임')||entry.title.$t):entry.title.$t;
    const article=document.createElement('article');article.className='ncp-r4-card'+(game?' ncp-game-visual':'');
    if(game&&count>0){const badge=document.createElement('span');badge.className='ncp-coupon-count';badge.textContent='코드 '+count+'개';article.append(badge);}
    const doc=new DOMParser().parseFromString(entry.content?.$t||'','text/html');
    let src=doc.querySelector('img')?.getAttribute('src')||entry.media$thumbnail?.url||'https://api.iconify.design/twemoji/video-game.svg';
    if(src&&new URL(src,location.href).protocol==='https:'){
      const image=document.createElement('img');image.className='ncp-r4-cover';image.alt=name;image.loading='lazy';image.decoding='async';image.referrerPolicy='no-referrer';
      const icon=new URL(src,location.href);if(icon.hostname==='play-lh.googleusercontent.com')icon.pathname=icon.pathname.replace(/=[^/]*$/, '=w400-h240-rw');image.src=icon.href;
      image.addEventListener('error',()=>{const fallback=entry.media$thumbnail?.url;if(fallback&&fallback!==image.src)image.src=fallback;else image.remove();},{once:true});const coverLink=document.createElement('a');coverLink.href=url;coverLink.className='ncp-game-cover-link';coverLink.append(image);article.append(coverLink);
    }
    const body=document.createElement('div');body.className='ncp-r4-card-body';
    const heading=document.createElement('h3');const link=document.createElement('a');link.href=url;link.textContent=name;if(game){link.textContent='';for(const part of name.split(/([A-Za-z0-9é]+(?:[ .:-][A-Za-z0-9é]+)*)/)){const segment=document.createElement('span');segment.textContent=part;if(/^[A-Za-z0-9é]/.test(part))segment.style.whiteSpace='nowrap';link.append(segment);}}heading.append(link);
    body.append(heading);article.append(body);return article;
  }
  function paginate(container,items,label){
    if(!items.length)return;const size=12,total=Math.ceil(items.length/size);let page=0;
    const controls=document.createElement('div');controls.className='ncp-r4-pager';controls.setAttribute('aria-label',label+' 페이지');
    const previous=document.createElement('button'),next=document.createElement('button'),position=document.createElement('span');
    previous.type=next.type='button';const arrow=direction=>'<svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="'+(direction==='left'?'M14 6l-6 6 6 6':'M10 6l6 6-6 6')+'" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';previous.innerHTML=arrow('left');next.innerHTML=arrow('right');previous.setAttribute('aria-label',label+' 이전 12개');next.setAttribute('aria-label',label+' 다음 12개');position.setAttribute('aria-live','polite');
    function render(){container.replaceChildren(...items.slice(page*size,(page+1)*size));previous.disabled=page===0;next.disabled=page===total-1;position.textContent=(page+1)+' / '+total;position.setAttribute('aria-label',(page+1)+'페이지, 전체 '+total+'페이지');}
    let moving=false;async function move(direction){const target=page+direction;if(moving||target<0||target>=total)return;moving=true;previous.disabled=next.disabled=true;try{if(!matchMedia('(prefers-reduced-motion: reduce)').matches){await container.animate([{transform:'translateX(0)',opacity:1},{transform:'translateX('+(-direction*24)+'px)',opacity:0}],{duration:140,easing:'ease-in'}).finished;page=target;render();previous.disabled=next.disabled=true;await container.animate([{transform:'translateX('+(direction*32)+'px)',opacity:0},{transform:'translateX(0)',opacity:1}],{duration:240,easing:'cubic-bezier(.22,1,.36,1)'}).finished;}else{page=target;render();}}finally{moving=false;previous.disabled=page===0;next.disabled=page===total-1;}}
    previous.addEventListener('click',()=>move(-1));next.addEventListener('click',()=>move(1));
    controls.append(previous,position,next);container.after(controls);render();
  }
  root.querySelectorAll('.ncp-r4-section-head a').forEach(link=>{link.textContent='전체 보기';link.classList.add('ncp-r4-view-all');});
  try{
    const response=await fetch('/feeds/posts/default?alt=json&max-results=150&orderby=updated');if(!response.ok)throw Error('FEED_HTTP');
    const entries=(await response.json()).feed.entry||[];const games=root.querySelector('.ncp-r4-game-list'),latest=root.querySelector('.ncp-r4-latest-list');
    const gameCards=[],seen=new Set();for(const entry of [...entries].sort((a,b)=>(Date.parse(b.published?.$t)||0)-(Date.parse(a.published?.$t)||0))){const labels=(entry.category||[]).map(x=>x.term);if(labels.includes('게임')){const name=labels.find(x=>x!=='게임')||entry.title.$t;if(!seen.has(name)){const item=card(entry,true,guideCodeCount(entry));if(item){gameCards.push(item);seen.add(name);}}}}
    const latestCards=entries.filter(x=>x.category?.some(c=>allowed.includes(c.term))).map(entry=>card(entry,false)).filter(Boolean);
    games.closest('section')?.querySelector('h2')?.setAttribute('title','최신 등록순');paginate(games,gameCards,'게임 쿠폰');paginate(latest,latestCards,'최근 업데이트');
    status.textContent='';if(!games.children.length)games.textContent='현재 표시 기준에 맞는 게임 쿠폰이 없습니다.';if(!latest.children.length)status.textContent='새 쿠폰 안내를 준비 중입니다.';
  }catch{status.textContent='목록을 불러오지 못했습니다. 카테고리 또는 검색으로 쿠폰을 찾아주세요.';}
})();

